package com.wanyuecity.energy.operation;
import com.wanyuecity.energy.core.ApiResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1/operations/clearances") public class OperationClearanceController{private final OperationClearanceService service;public OperationClearanceController(OperationClearanceService service){this.service=service;}@GetMapping("/period")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','APPLICANT','DEVICE_VERIFIER','VIEWER')")public ApiResponse<Map<String,Object>>period(){return ApiResponse.ok(service.currentPeriod());}@PostMapping("/stall/{token}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','APPLICANT','VIEWER')")public ApiResponse<Map<String,Object>>submit(@PathVariable String token,@RequestBody Map<String,Object>b,Authentication a){return ApiResponse.ok(service.submit(token,b,a.getName()));}@GetMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','APPLICANT','DEVICE_VERIFIER')")public ApiResponse<Map<String,Object>>page(@RequestParam(defaultValue="")String keyword,@RequestParam(defaultValue="")String periodDate,@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize,Authentication a){boolean all=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_SUPER_ADMIN")||x.getAuthority().equals("ROLE_SYSTEM_ADMIN")||x.getAuthority().equals("ROLE_DEVICE_VERIFIER"));return ApiResponse.ok(service.page(a.getName(),all,keyword,periodDate,pageNum,pageSize));}}
